// Minimal stand-in for @minecraft/server used by tools/smoke_test.mjs.
const subs = {};
const ev = (n) => ({ subscribe: (f) => { (subs[n] ??= []).push(f); return f; } });
export const __subs = subs;
export const cmds = [];
export const spawned = [];
let sets = 0;
export const stats = () => ({ sets, cmds: cmds.length, spawned: spawned.length });
const props = {};
export const blocks = new Map();
const dim = {
  id: "minecraft:overworld",
  runCommand(c) { if (/\bundefined\b|NaN/.test(c)) throw new Error("bad command " + c); cmds.push(c);
    const m = c.match(/^fill (-?\d+) (-?\d+) (-?\d+) (-?\d+) (-?\d+) (-?\d+) (\S+)/);
    if (m) {
      const [a, b, d, e, f, g] = m.slice(1, 7).map(Number);
      for (let x = a; x <= e; x++) for (let y = b; y <= f; y++) for (let z = d; z <= g; z++) {
        if (m[7] === "agartha:portal") blocks.set(`${x},${y},${z}`, m[7]);
        else if ((e - a + 1) * (f - b + 1) * (g - d + 1) < 64) blocks.delete(`${x},${y},${z}`);
      }
    }
    return { successCount: 1 }; },
  getBlock(l) {
    const key = `${Math.floor(l.x)},${Math.floor(l.y)},${Math.floor(l.z)}`;
    return {
      location: { x: Math.floor(l.x), y: Math.floor(l.y), z: Math.floor(l.z) },
      typeId: blocks.get(key) ?? "minecraft:air",
      setPermutation(p) { sets++; if (p?.type?.id === "agartha:portal") blocks.set(key, p.type.id); },
      setType(t) { blocks.set(key, t); },
    };
  },
  getEntities() { return []; },
  spawnParticle() {},
  playSound() {},
  getPlayers() { return []; },
  spawnEntity(id, l) { spawned.push([id, l]); return { typeId: id, location: l, dimension: dim, teleport() {}, playAnimation() {}, remove() {} }; },
  spawnItem(item, l) { spawned.push([item.typeId, l]); },
};
const jobs = [], intervals = [], timeouts = [];
export const system = {
  currentTick: 0,
  afterEvents: new Proxy({}, { get: (_, n) => ev("system." + n) }),
  runJob(g) { jobs.push(g); },
  runInterval(f, n) { intervals.push([f, n]); },
  runTimeout(f, n) { timeouts.push([f, system.currentTick + n]); },
  __tick(budget = 20000) {
    system.currentTick++;
    for (const g of [...jobs]) for (let i = 0; i < budget; i++) if (g.next().done) { jobs.splice(jobs.indexOf(g), 1); break; }
    for (const [f, n] of intervals) if (system.currentTick % n === 0) f();
    for (const t of [...timeouts]) if (t[1] <= system.currentTick) { timeouts.splice(timeouts.indexOf(t), 1); t[0](); }
  },
  __busy: () => jobs.length > 0,
};
const messages = [];
export const __messages = messages;
export const world = {
  afterEvents: new Proxy({}, { get: (_, n) => ev(n) }),
  getDimension: () => dim,
  getDynamicProperty: (k) => props[k],
  setDynamicProperty: (k, v) => { props[k] = v; },
  getAllPlayers: () => players,
  getDefaultSpawnLocation: () => ({ x: 0, y: 32767, z: 0 }),
  sendMessage: (m) => messages.push(m),
};
export const BlockPermutation = {
  resolve(id, s) {
    if (id === "minecraft:bogus") throw new Error("unknown block");
    return { type: { id }, getAllStates: () => ({ ...(s ?? {}) }) };
  },
};
export const GameMode = { Creative: "Creative", Spectator: "Spectator", Survival: "Survival" };
export const EquipmentSlot = { Mainhand: "Mainhand" };
export class ItemStack { constructor(typeId, amount = 1) { this.typeId = typeId; this.amount = amount; } }
const players = [];
export function makePlayer() {
  const tags = new Set(), dp = {}, log = [];
  const p = {
    id: "p" + players.length, typeId: "minecraft:player", isValid: true, location: { x: 10, y: 70, z: 10 }, dimension: dim, log,
    hasTag: (t) => tags.has(t), addTag: (t) => tags.add(t), removeTag: (t) => tags.delete(t),
    getDynamicProperty: (k) => dp[k], setDynamicProperty: (k, v) => { dp[k] = v; },
    teleport(l) { log.push(["tp", { ...l }]); p.location = { ...l }; }, addEffect() {}, removeEffect() {},
    runCommand(c) { log.push(["cmd", c]); }, sendMessage(m) { log.push(["msg", m]); }, playSound() {},
    kill() { log.push(["kill"]); return true; }, getSpawnPoint: () => undefined,
    mode: "Survival", getGameMode() { return p.mode; }, setGameMode(m) { p.mode = m; log.push(["mode", m]); },
    getViewDirection: () => ({ x: 0, y: 0, z: -1 }),
    items: [], mainhand: undefined,
    getComponent(n) {
      if (n === "minecraft:inventory") return { container: { addItem(it) { p.items.push(it.typeId); p.mainhand = it; } } };
      if (n === "minecraft:equippable") return { getEquipment: () => p.mainhand, setEquipment(_, it) { p.mainhand = it; if (!it) p.items.pop(); } };
    },
    onScreenDisplay: { setActionBar() {}, setTitle(t) { log.push(["title", t]); } },
  };
  players.push(p);
  return p;
}
